<?php
namespace App\Services\Marketing;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Carbon\CarbonImmutable;
/** All dashboard/table/export filters use this single owner-scoped report. */
class MarketingAnalytics {
 public function report(Request $r):array{$v=$r->validate(['campaign'=>'nullable|uuid','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from','timezone'=>'nullable|timezone']);$tz=$v['timezone']??'Asia/Kuala_Lumpur';$to=CarbonImmutable::parse($v['to']??now($tz)->toDateString(),$tz)->endOfDay();$from=CarbonImmutable::parse($v['from']??$to->subDays(6)->toDateString(),$tz)->startOfDay();abort_if($to->diffInDays($from,true)>93,422,'Choose a reporting period of 93 days or less.');$start=$from->utc();$end=$to->utc();$campaigns=app(MarketingCampaigns::class)->query($r->user()->id)->when($v['campaign']??null,fn($q,$id)=>$q->whereKey($id))->get()->keyBy('id');$ids=$campaigns->keys();$types=['campaign_link_click','website_sessions','page_view','view_item','add_to_cart','begin_checkout','request_quote','quotation_sent','quotation_accepted','purchase'];$summary=array_fill_keys($types,0);$rows=[];foreach($campaigns as $c)$rows[$c->id]=array_merge(['id'=>$c->id,'name'=>$c->name,'objective'=>$c->objective],array_fill_keys($types,0));$trend=[];for($day=$from;$day->lte($to);$day=$day->addDay())$trend[$day->toDateString()]=['date'=>$day->toDateString(),'sessions'=>0,'checkouts'=>0,'quote_requests'=>0,'paid_orders'=>0];$alias=['request'=>'campaign_link_click','arrival'=>'website_sessions','checkout'=>'begin_checkout'];$visits=[];$campaignVisits=[];$count=0;foreach(DB::table('marketing_analytics_events')->whereIn('campaign_id',$ids)->whereBetween('occurred_at',[$start,$end])->orderBy('id')->cursor() as $event){abort_if(++$count>200000,422,'Choose a narrower reporting period.');$kind=$alias[$event->kind]??$event->kind;if(!array_key_exists($kind,$summary))continue;if($kind==='website_sessions'){$sid=$event->session_key?:'event:'.$event->id;$fresh=!isset($visits[$sid]);$visits[$sid]=true;$summary[$kind]=count($visits);$campaignVisits[$event->campaign_id][$sid]=true;$rows[$event->campaign_id][$kind]=count($campaignVisits[$event->campaign_id]);}else{$summary[$kind]++;$rows[$event->campaign_id][$kind]++;}$day=CarbonImmutable::parse($event->occurred_at,'UTC')->tz($tz)->toDateString();if(isset($trend[$day])){if($kind==='website_sessions'&&$fresh)$trend[$day]['sessions']++;if($kind==='begin_checkout')$trend[$day]['checkouts']++;}}
 $enquiries=DB::table('marketing_enquiry_attributions')->whereIn('campaign_id',$ids)->whereBetween('submitted_at',[$start,$end]);foreach((clone $enquiries)->select('campaign_id')->selectRaw('COUNT(*) as total')->groupBy('campaign_id')->get() as $e){$summary['request_quote']+=(int)$e->total;$rows[$e->campaign_id]['request_quote']=(int)$e->total;}foreach((clone $enquiries)->select('submitted_at')->cursor() as $e){$day=CarbonImmutable::parse($e->submitted_at,'UTC')->tz($tz)->toDateString();if(isset($trend[$day]))$trend[$day]['quote_requests']++;}
 $paid=DB::table('marketing_order_attributions')->whereIn('campaign_id',$ids)->where('state','paid')->whereBetween('paid_at',[$start,$end]);$money=(clone $paid)->select('campaign_id','base_currency')->selectRaw('COUNT(*) as paid_orders, SUM(base_minor) as paid_minor, SUM(refunded_minor) as refunded_minor')->groupBy('campaign_id','base_currency')->get();foreach($money as $m){$summary['purchase']+=(int)$m->paid_orders;$rows[$m->campaign_id]['purchase']+=(int)$m->paid_orders;}foreach((clone $paid)->select('paid_at')->cursor() as $a){$day=CarbonImmutable::parse($a->paid_at,'UTC')->tz($tz)->toDateString();if(isset($trend[$day]))$trend[$day]['paid_orders']++;}$history=(clone $paid)->leftJoin('orders','orders.id','=','marketing_order_attributions.order_id')->select('marketing_order_attributions.order_id','orders.number','marketing_order_attributions.campaign_id','base_currency','base_minor','refunded_minor','paid_at','policy')->orderByDesc('paid_at')->limit(25)->get();$totals=$money->groupBy('base_currency')->map(fn($g,$currency)=>['currency'=>$currency,'paid_minor'=>(int)$g->sum('paid_minor'),'refunded_minor'=>(int)$g->sum('refunded_minor'),'net_minor'=>(int)$g->sum('paid_minor')-(int)$g->sum('refunded_minor')])->values();return ['retention'=>['event_days'=>(int)config('marketing.privacy.event_days',90),'activity_since'=>now()->subDays((int)config('marketing.privacy.event_days',90))->toIso8601String(),'financial_records_retained'=>true],'currency_totals'=>$totals,'collection'=>app(MarketingAttribution::class)->enabled()?'enabled':'disabled','paid_orders'=>$summary['purchase'],'quote_requests'=>$summary['request_quote'],'summary'=>$summary,'campaigns'=>array_values($rows),'trend'=>array_values($trend),'money'=>$money,'history'=>$history,'history_limit'=>25,'unconfirmed'=>DB::table('marketing_order_attributions')->whereIn('campaign_id',$ids)->whereIn('state',['evidence_unconfirmed','money_unconfirmed'])->count(),'policy'=>'Last eligible click · 7-day window','filters'=>['campaign'=>$v['campaign']??null,'from'=>$from->toDateString(),'to'=>$to->toDateString(),'timezone'=>$tz],'refund_basis'=>'Confirmed refunds to date on orders paid within the selected period','as_of'=>now()->toIso8601String()];}
}
